ALTER TABLE users ADD COLUMN IF NOT EXISTS session_version INT NOT NULL DEFAULT 0;
ALTER TABLE users ADD COLUMN IF NOT EXISTS preferences JSONB NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE reviews ADD COLUMN IF NOT EXISTS is_sample BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE product_qa ADD COLUMN IF NOT EXISTS is_sample BOOLEAN NOT NULL DEFAULT FALSE;
ALTER TABLE orders DROP CONSTRAINT IF EXISTS orders_status_check;
ALTER TABLE orders ADD CONSTRAINT orders_status_check CHECK(status IN ('awaiting_payment','placed','packed','shipped','out_for_delivery','delivered','cancelled'));
ALTER TABLE orders DROP CONSTRAINT IF EXISTS orders_payment_method_check;
ALTER TABLE orders ADD CONSTRAINT orders_payment_method_check CHECK(payment_method IN ('razorpay','cod','demo'));
ALTER TABLE orders ADD COLUMN IF NOT EXISTS coupon_id UUID REFERENCES coupons(id);
ALTER TABLE orders ADD COLUMN IF NOT EXISTS payment_expires_at TIMESTAMPTZ;
ALTER TABLE orders ADD COLUMN IF NOT EXISTS delivery_method TEXT NOT NULL DEFAULT 'standard';
ALTER TABLE order_items ADD COLUMN IF NOT EXISTS delivered_at TIMESTAMPTZ;
UPDATE order_items i SET delivered_at=(SELECT MIN(e.created_at) FROM order_status_events e WHERE e.order_id=i.order_id AND e.status='delivered') WHERE i.status IN('delivered','returned') AND i.delivered_at IS NULL;
ALTER TABLE stock_holds ADD COLUMN IF NOT EXISTS order_id UUID REFERENCES orders(id) ON DELETE CASCADE;
ALTER TABLE stock_holds ADD COLUMN IF NOT EXISTS batch_id UUID;
ALTER TABLE returns ADD COLUMN IF NOT EXISTS resolution TEXT NOT NULL DEFAULT 'refund';
ALTER TABLE returns ADD COLUMN IF NOT EXISTS refund_id TEXT;
CREATE INDEX IF NOT EXISTS idx_holds_variant_expiry ON stock_holds(variant_id,expires_at);
CREATE INDEX IF NOT EXISTS idx_holds_user ON stock_holds(user_id);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_return_per_item ON returns(order_item_id) WHERE status NOT IN ('rejected');
CREATE TABLE IF NOT EXISTS coupon_redemptions(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),coupon_id UUID REFERENCES coupons(id),user_id UUID REFERENCES users(id),order_id UUID UNIQUE REFERENCES orders(id),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,hits INT NOT NULL,expires_at TIMESTAMPTZ NOT NULL);
CREATE TABLE IF NOT EXISTS password_resets(token_hash TEXT PRIMARY KEY,user_id UUID REFERENCES users(id) ON DELETE CASCADE,expires_at TIMESTAMPTZ NOT NULL,used_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS assistant_messages(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),user_id UUID REFERENCES users(id) ON DELETE CASCADE,role TEXT NOT NULL,content TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS review_votes(review_id UUID REFERENCES reviews(id) ON DELETE CASCADE,user_id UUID REFERENCES users(id) ON DELETE CASCADE,PRIMARY KEY(review_id,user_id));
CREATE TABLE IF NOT EXISTS review_reports(review_id UUID REFERENCES reviews(id) ON DELETE CASCADE,user_id UUID REFERENCES users(id) ON DELETE CASCADE,reason TEXT,PRIMARY KEY(review_id,user_id));
CREATE TABLE IF NOT EXISTS uploads(id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),user_id UUID REFERENCES users(id),mime TEXT NOT NULL,data TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
ALTER TABLE uploads ADD COLUMN IF NOT EXISTS private BOOLEAN NOT NULL DEFAULT FALSE;
CREATE TABLE IF NOT EXISTS webhook_events(id TEXT PRIMARY KEY,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE OR REPLACE FUNCTION immutable_audit() RETURNS trigger AS $$ BEGIN RAISE EXCEPTION 'Audit log is append only'; END; $$ LANGUAGE plpgsql;
DROP TRIGGER IF EXISTS audit_append_only ON audit_logs;
CREATE TRIGGER audit_append_only BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION immutable_audit();
